-- pact: accounts + notes.
--
-- Model
--   * One `profiles` row per auth user (created by a trigger on first sign-in).
--   * `notebooks` and `notes` belong to their owner. Ids are generated by the client (so an offline-created note
--     already has its id) and are only unique *per owner*, hence the composite primary keys. Nothing here is ever
--     readable by another user: every policy is "owner_id = the signed-in user".
--   * Deletes are soft (`deleted_at`) so a deletion made on one device reaches the others (sync tombstones).
--   * `modified_at` (when the row last changed in ANY field, set by the client) orders sync: last write wins.
--     `updated_at` on notes is the *content* edit time shown in the UI (pinning doesn't change it).
--
-- Security notes (see the Supabase skill checklist)
--   * RLS is enabled on every table; `anon` has no access at all.
--   * UPDATE policies have both USING and WITH CHECK so a row can't be re-assigned to someone else.
--   * The only SECURITY DEFINER function lives in the unexposed `private` schema and has EXECUTE revoked.
--   * No policy or function reads `user_metadata` for authorisation (it is user-editable). It is only used to
--     suggest a default username / display name.

create schema if not exists private;
revoke all on schema private from public, anon, authenticated;

-- ── profiles ─────────────────────────────────────────────────────────────────

create table public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  username text not null,
  display_name text not null default '',
  designation text not null default '',
  bio text not null default '',
  contact_email text,
  -- The welcome flow has been completed (so a new device doesn't greet a returning user as a stranger).
  onboarded boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint profiles_username_format check (username ~ '^[a-z0-9_]{3,20}$'),
  constraint profiles_text_lengths check (
    char_length(display_name) <= 40
    and char_length(designation) <= 60
    and char_length(bio) <= 160
    and char_length(coalesce(contact_email, '')) <= 120
  )
);

create unique index profiles_username_key on public.profiles (username);

alter table public.profiles enable row level security;

-- Own row only for now. (Looking people up by username arrives with friends, via a narrow function, not by opening
-- this table to everyone.)
create policy "profiles: read own" on public.profiles for select to authenticated using ((select auth.uid()) = id);
create policy "profiles: insert own" on public.profiles for insert to authenticated with check ((select auth.uid()) = id);
create policy "profiles: update own" on public.profiles for update to authenticated
  using ((select auth.uid()) = id) with check ((select auth.uid()) = id);

revoke all on table public.profiles from anon, authenticated;
grant select, insert, update on table public.profiles to authenticated;

-- A profile for every new user, with a unique, valid username suggested from the provider's handle or the email.
create function private.handle_new_user() returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  base text;
  candidate text;
begin
  base := lower(regexp_replace(
    coalesce(
      nullif(new.raw_user_meta_data ->> 'user_name', ''),
      nullif(new.raw_user_meta_data ->> 'preferred_username', ''),
      nullif(split_part(coalesce(new.email, ''), '@', 1), ''),
      'user'
    ),
    '[^a-zA-Z0-9_]', '', 'g'));
  if char_length(base) < 3 then
    base := 'user' || base;
  end if;
  base := left(base, 15);
  candidate := base;
  while exists (select 1 from public.profiles p where p.username = candidate) loop
    candidate := base || substr(md5(random()::text || clock_timestamp()::text), 1, 4);
  end loop;

  insert into public.profiles (id, username, display_name)
  values (
    new.id,
    candidate,
    left(coalesce(nullif(new.raw_user_meta_data ->> 'full_name', ''), nullif(new.raw_user_meta_data ->> 'name', ''), ''), 40)
  )
  on conflict (id) do nothing;
  return new;
end;
$$;

revoke all on function private.handle_new_user() from public, anon, authenticated;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function private.handle_new_user();

-- ── notebooks ────────────────────────────────────────────────────────────────

create table public.notebooks (
  owner_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  id text not null,
  name text not null,
  next_number integer not null default 1,
  created_at timestamptz not null default now(),
  modified_at timestamptz not null default now(),
  deleted_at timestamptz,
  primary key (owner_id, id),
  constraint notebooks_id_length check (char_length(id) between 1 and 64),
  constraint notebooks_name_length check (char_length(name) <= 120),
  constraint notebooks_next_number_positive check (next_number >= 1)
);

-- ── notes ────────────────────────────────────────────────────────────────────

create table public.notes (
  owner_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  id text not null,
  notebook_id text not null,
  number integer not null default 0,
  title text not null default '',
  body text not null default '',
  pinned boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  modified_at timestamptz not null default now(),
  deleted_at timestamptz,
  primary key (owner_id, id),
  foreign key (owner_id, notebook_id) references public.notebooks (owner_id, id) on delete cascade,
  constraint notes_id_length check (char_length(id) between 1 and 64),
  constraint notes_title_length check (char_length(title) <= 500),
  constraint notes_body_length check (char_length(body) <= 500000)
);

-- The composite FK needs an index of its own, and pulls read "everything for this owner, newest first".
create index notes_notebook_idx on public.notes (owner_id, notebook_id);
create index notes_owner_modified_idx on public.notes (owner_id, modified_at desc);
create index notebooks_owner_modified_idx on public.notebooks (owner_id, modified_at desc);

-- ── RLS for notebooks and notes ──────────────────────────────────────────────

alter table public.notebooks enable row level security;
alter table public.notes enable row level security;

create policy "notebooks: read own" on public.notebooks for select to authenticated using ((select auth.uid()) = owner_id);
create policy "notebooks: insert own" on public.notebooks for insert to authenticated with check ((select auth.uid()) = owner_id);
create policy "notebooks: update own" on public.notebooks for update to authenticated
  using ((select auth.uid()) = owner_id) with check ((select auth.uid()) = owner_id);
create policy "notebooks: delete own" on public.notebooks for delete to authenticated using ((select auth.uid()) = owner_id);

create policy "notes: read own" on public.notes for select to authenticated using ((select auth.uid()) = owner_id);
create policy "notes: insert own" on public.notes for insert to authenticated with check ((select auth.uid()) = owner_id);
create policy "notes: update own" on public.notes for update to authenticated
  using ((select auth.uid()) = owner_id) with check ((select auth.uid()) = owner_id);
create policy "notes: delete own" on public.notes for delete to authenticated using ((select auth.uid()) = owner_id);

revoke all on table public.notebooks, public.notes from anon, authenticated;
grant select, insert, update, delete on table public.notebooks, public.notes to authenticated;

-- ── Realtime: other devices see changes as they happen (RLS still applies to what each subscriber receives) ──

alter publication supabase_realtime add table public.notebooks, public.notes;
